#!/usr/bin/env node
/**
 * ONE-OFF, TEST-ONLY key generation script — mirrors the manual, offline
 * procedure defined for the REAL production signing key, but this
 * script and the key it produces are for development/CI testing of the
 * addon-registry verify logic ONLY.
 *
 * THIS IS NOT THE PRODUCTION KEY. Do not pin this key's output into a
 * release build as a trusted publisher key beyond the placeholder entry in
 * electron/addons/signing.ts. The real key does not exist yet — it is
 * generated by a maintainer, offline, under the exact custody
 * procedure this script mirrors.
 *
 * Run manually: node tests/addons/fixtures/generate-test-signing-key.cjs
 * Prints the public key (PEM), private key (PEM, TEST ONLY), and keyId.
 */
const crypto = require("crypto");

const { publicKey, privateKey } = crypto.generateKeyPairSync("ed25519");

const publicKeyPem = publicKey.export({ type: "spki", format: "pem" }).toString();
const privateKeyPem = privateKey.export({ type: "pkcs8", format: "pem" }).toString();

// keyId = first 8 hex chars of sha256(raw public key bytes).
const publicKeyDer = publicKey.export({ type: "spki", format: "der" });
const keyId = crypto.createHash("sha256").update(publicKeyDer).digest("hex").slice(0, 8);

console.log(JSON.stringify({ keyId, publicKeyPem, privateKeyPem }, null, 2));
